import { immutableJSONPatch, type JSONPatchDocument } from "immutable-json-patch";
import {
  type Utterance,
  type ConversationEvent,
  type InspectorEventType,
  type StackEvent,
  type UnionEventType,
  ConversationEventType,
  UtteranceType,
  type RawEvent,
  type EventMetadata,
  type UtteranceIntent,
  type MessageIntent,
  type BackendResponseData,
  type ResponseData,
  type QuickReply,
  type Button,
  type SlotState,
} from "../types";

export const eventTexts: { [key: string]: string } = {
  [ConversationEventType.FlowCancelled]: " cancelled",
  [ConversationEventType.FlowCompleted]: " completed",
  [ConversationEventType.FlowStarted]: " started",
  [ConversationEventType.FlowInterrupted]: " interrupted",
  [ConversationEventType.FlowResumed]: " resumed",
};

export const isInternalRasaSlot = (slotName: string) => {
  // Slots that we hide from the UI as they aren't user-facing and won't be
  // helpful for debugging
  return ["flow_hashes", "dialogue_stack"].includes(slotName);
};

export const isInternalRasaAction = (actionName: string) => {
  // Actions that we hide from the UI as they aren't user-facing and won't be
  // helpful for debugging
  return ["action_run_slot_rejections"].includes(actionName);
};

export const isInternalRasaEvent = (eventName: string) => {
  // Events that we hide from the UI as they aren't user-facing and won't be
  // helpful for debugging
  return ["session_started", "user_featurization"].includes(eventName);
};

export const isInternalRasaMessage = (message: string) => {
  // Messages that are internally generated by Rasa and not user-facing
  return ["/session_start", "/silence_timeout"].includes(message);
};

export const isInternalRasaFlow = (flowId: string) => {
  // These two flows use features that are not supported in the UI yet, so
  // even if they might be helpful, we can't show them.
  // - pattern_collect_information uses a loop
  return ["pattern_collect_information"].includes(flowId);
};

interface StackFrame {
  flow_id: string;
  step_id: string;
}

export function isConversationEvent(event: InspectorEventType): event is ConversationEvent {
  return event.__typename === "ConversationEvent";
}

export function isStreamingFrame(event: RawEvent) {
  return event.event === "bot" && event.metadata?.streaming;
}

export function isStreamingUtterance(event: UnionEventType) {
  return isUtterance(event) && event?.metadata?.streaming;
}

function updateStackWithEvent(stack: StackFrame[], event: StackEvent): StackFrame[] {
  if (event.update) {
    const stackUpdate = JSON.parse(event.update) as JSONPatchDocument;
    return immutableJSONPatch(stack, stackUpdate);
  }
  return stack;
}

function hasFlowAtTheTopOfStack(stack: StackFrame[]): boolean {
  return stack.length > 0 && stack[stack.length - 1].flow_id !== undefined;
}

export const flowStepTrail = (events: InspectorEventType[]): Record<string, string[]> => {
  let stack: StackFrame[] = [];
  // mapping from flow id to the steps that were active in that flow, including loops
  let activeSteps: { [key: string]: string[] } = {};
  for (const event of events) {
    if (
      isConversationEvent(event) &&
      event.conversationEventType === ConversationEventType.Restart
    ) {
      stack = [];
      activeSteps = {};
    } else if (isStackEvent(event)) {
      stack = updateStackWithEvent(stack, event);
      if (!hasFlowAtTheTopOfStack(stack)) {
        continue;
      }
      const topFrame = stack[stack.length - 1];
      if (!activeSteps[topFrame.flow_id] || topFrame.step_id === "START") {
        activeSteps[topFrame.flow_id] = [];
      }
      activeSteps[topFrame.flow_id].push(topFrame.step_id);
    }
  }
  return activeSteps;
};

export function extractSlotEventsForFlow(
  events: ConversationEvent[],
  flowName: string,
): ConversationEvent[] {
  const activeFlows: string[] = [];
  const result: ConversationEvent[] = [];

  for (const event of events) {
    if (isMemoryWriteEvent(event)) {
      if (activeFlows[activeFlows.length - 1] === flowName) {
        result.push(event);
      }
      continue;
    }

    switch (event.conversationEventType) {
      case ConversationEventType.FlowStarted: {
        if (event.flowId) {
          // Mark flow as active by pushing it on the stack
          activeFlows.push(event.flowId);
        }
        break;
      }

      case ConversationEventType.FlowCompleted:
      case ConversationEventType.FlowCancelled: {
        // Attempt to pop if the top of the stack matches the flow that ended
        const endedFlow = event.metadata.flow_id;
        if (endedFlow && activeFlows[activeFlows.length - 1] === endedFlow) {
          activeFlows.pop();
        }
        break;
      }

      default:
        break;
    }
  }

  return result;
}

export function extractSlotEventsForSession(events: ConversationEvent[]): ConversationEvent[] {
  const sessionStartIndex = events.findLastIndex(
    (event) => event.conversationEventType === ConversationEventType.SessionStarted,
  );

  if (sessionStartIndex === -1) {
    return [];
  }

  return events.filter((event, index) => index >= sessionStartIndex && isMemoryWriteEvent(event));
}

export function formatSlots(slotEvents: ConversationEvent[]): SlotState[] {
  const slotMap = new Map<string, { value: unknown; event: ConversationEvent }>();

  slotEvents.forEach((event) => {
    if (event.name) {
      slotMap.set(event.name, { value: event.slotValue, event });
    }
  });

  return Array.from(slotMap.entries()).map(([name, { value, event }]) => ({
    name,
    value,
    event,
  }));
}

export const isSystemSlotEvent = (slotName: string) =>
  [
    "silence_timeout",
    "consecutive_silence_timeouts",
    "session_started_metadata",
    "flow_hashes",
    "requested_slot",
    "confirm_correction",
    "language",
    "max_clarification_options",
  ].includes(slotName);

const DISCOVERED_MEMORY_ENTRY = "__discovered__";

/**
 * Whether a memory-write entry is engine housekeeping the chat log hides:
 * system slots and the `system.` namespace, except the surfaced
 * `system.__discovered__` scratchpad. The conversation log row and the
 * tool-call grouping must share this single predicate — if they diverge, a
 * hidden write can still count toward a caret that then renders nothing.
 */
export const isHiddenSystemMemoryEntry = (entryName: string): boolean => {
  const isDiscoveredEntry = entryName.split(".").pop() === DISCOVERED_MEMORY_ENTRY;
  return isSystemSlotEvent(entryName) || (entryName.startsWith("system.") && !isDiscoveredEntry);
};

export const hasDisplayableSlotData = (
  slotRelatedEvents: ConversationEvent[],
  slots: Record<string, unknown>,
): boolean => {
  if (slotRelatedEvents.length > 0) {
    return true;
  }

  return Object.entries(slots).some(([name, value]) => isSystemSlotEvent(name) && value != null);
};

export const getSlotRelatedEvents = (events: UnionEventType[]): ConversationEvent[] => {
  return events.filter((event) => {
    if (!isConversationEvent(event)) {
      return false;
    }

    if (isMemoryWriteEvent(event)) {
      return true;
    }

    if (
      event.conversationEventType === ConversationEventType.FlowStarted ||
      event.conversationEventType === ConversationEventType.FlowCompleted ||
      event.conversationEventType === ConversationEventType.FlowCancelled
    ) {
      if (event.flowId?.startsWith("pattern_")) {
        return false;
      }
      return true;
    }

    if (event.conversationEventType === ConversationEventType.SessionStarted) {
      return true;
    }

    return false;
  }) as ConversationEvent[];
};

export function isUtterance(event: UnionEventType): event is Utterance {
  return (
    (event as Utterance).type === UtteranceType.Bot ||
    (event as Utterance).type === UtteranceType.User
  );
}

export function isBotUtteranceEmpty(utterance: Omit<Utterance, "entities">): boolean {
  return (
    utterance.type === UtteranceType.Bot &&
    !utterance.text &&
    !utterance.responseData?.image &&
    !utterance.responseData?.custom &&
    !utterance.responseData?.attachment &&
    !utterance.responseData?.buttons?.length &&
    !utterance.responseData?.quickReplies?.length
  );
}

export function isStackEvent(event: InspectorEventType): event is StackEvent {
  return event.__typename === "StackEvent";
}

/** First `[label](url)` in text; linear scan, no regex (avoids ReDoS static analysis). */
function extractFirstMarkdownLinkUrl(text: string): string | undefined {
  const bracketStart = text.indexOf("[");
  if (bracketStart === -1) {
    return undefined;
  }

  const bracketEnd = text.indexOf("]", bracketStart + 1);
  if (bracketEnd === -1) {
    return undefined;
  }

  let i = bracketEnd + 1;
  while (i < text.length && (text[i] === " " || text[i] === "\t")) {
    i += 1;
  }

  if (text[i] !== "(") {
    return undefined;
  }

  const urlStart = i + 1;
  const parenEnd = text.indexOf(")", urlStart);
  if (parenEnd === -1) {
    return undefined;
  }

  return text.slice(urlStart, parenEnd);
}

export function generateResponseData(response: BackendResponseData): ResponseData {
  const result: ResponseData = {
    buttons: [],
    quickReplies: [],
  };

  if (response.text) {
    const linkUrl = extractFirstMarkdownLinkUrl(response.text);
    if (linkUrl !== undefined) {
      result.attachment = linkUrl;
    }
  }

  if (typeof response.image === "string") {
    result.image = response.image;
  }

  if (response.attachment) {
    if (response.attachment.type === "image") {
      result.image = response.attachment.payload.src;
    }
    if (response.attachment.type === "link") {
      result.attachment = response.attachment.payload.url;
    }
    if (response.attachment.type === "template") {
      result.elements = response.attachment.payload.elements;
    }
  }

  if (response.quick_replies) {
    result.quickReplies = response.quick_replies.map(
      (quickReply: QuickReply & { image_url?: string }) => ({
        title: quickReply.title,
        payload: quickReply.payload,
        imageUrl: quickReply.image_url,
      }),
    );
  }

  if (response.buttons) {
    result.quickReplies = response.buttons.map((button: Button & { image_url?: string }) => ({
      title: button.title,
      payload: button.payload,
      imageUrl: button.image_url,
    }));
  }

  if (response.elements) {
    result.elements = response.elements;
  }

  result.custom = checkForCustomElements(response);

  return result;
}

function checkForCustomElements(
  response: Record<string, unknown>,
): Record<string, unknown> | undefined {
  const keys = ["text", "attachment", "quick_replies", "buttons", "elements", "image"];
  const customElements: Record<string, unknown> = {};

  for (const key in response) {
    if (response.hasOwnProperty(key) && !keys.includes(key) && response[key] !== null) {
      customElements[key] = response[key];
    }
  }

  if (Object.keys(customElements).length > 0) {
    return customElements;
  }

  return undefined;
}

/** True for Mantle `tool_executed` and CALM `mcp_tool_executed`. */
export function isToolRunEvent(event: UnionEventType): event is ConversationEvent & {
  conversationEventType: ConversationEventType.McpToolExecuted | ConversationEventType.ToolExecuted;
} {
  return (
    "conversationEventType" in event &&
    (event.conversationEventType === ConversationEventType.McpToolExecuted ||
      event.conversationEventType === ConversationEventType.ToolExecuted)
  );
}

const FLOW_LIFECYCLE_EVENT_TYPES: ReadonlySet<ConversationEventType> = new Set([
  ConversationEventType.FlowStarted,
  ConversationEventType.FlowCompleted,
  ConversationEventType.FlowCancelled,
  ConversationEventType.FlowInterrupted,
  ConversationEventType.FlowResumed,
]);

export function isFlowLifecycleEvent(event: UnionEventType): boolean {
  return (
    "conversationEventType" in event && FLOW_LIFECYCLE_EVENT_TYPES.has(event.conversationEventType)
  );
}

export function isMemoryWriteEvent(event: UnionEventType): boolean {
  return (
    "conversationEventType" in event &&
    (event.conversationEventType === ConversationEventType.Slot ||
      event.conversationEventType === ConversationEventType.MemorySet ||
      event.conversationEventType === ConversationEventType.MemoryCleared)
  );
}

/**
 * Stable identity for a mapped tracker event. The tracker is append-only, so an
 * event never changes once written and its array position never shifts — the
 * (index, type, timestamp) triple therefore names the same event across every
 * mapping run. Stable ids let selection and expansion state survive tracker
 * updates without workaround keys. When the wire format gains a real event id it
 * replaces this derivation.
 */
export function deterministicEventId(event: RawEvent, index: number): string {
  return `event-${index}-${event.event}-${event.timestamp}`;
}

export function mapRawEventsToConversationEvents(events: RawEvent[]): UnionEventType[] {
  const mappedEvents = events.map((event, index) => {
    if (!event.metadata) {
      event.metadata = {} as EventMetadata;
    }

    // this is a fix, since some events store the flow id under a differnet key...
    // e.g. bot uttered, set slot, action
    event.metadata.flow_id = event.metadata.active_flow || event.metadata.flow_id;

    const parsedTimestamp = new Date(event.timestamp * 1000).toISOString();
    const eventId = deterministicEventId(event, index);

    switch (event.event) {
      case "user" as const: {
        const intents: UtteranceIntent[] =
          event.parse_data?.intent_ranking?.map((intent: MessageIntent, intentIndex: number) => ({
            id: `${eventId}-intent-${intentIndex}`,
            name: intent.name,
            confidence: intent.confidence,
          })) || [];

        return {
          id: eventId,
          conversationId: event.conversation_id,
          machineLearningModelId: "",
          entities: [],
          intents,
          text: event.text,
          tokens: [],
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          type: UtteranceType.User,
          __typename: "Utterance",
          rephrase: false,
          rephrasePrompt: null,
          commands: event.parse_data?.commands,
          metadata: {
            ...event.metadata,
            parseData: event.parse_data,
            rawEvent: event,
          },
        };
      }
      case "bot" as const:
        return {
          id: eventId,
          conversationId: event.conversation_id,
          machineLearningModelId: "",
          entities: [],
          intents: [],
          text: event.text || "",
          responseData: generateResponseData({
            ...event.data,
            text: event.text,
          }),
          tokens: [],
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          type: UtteranceType.Bot,
          commands: null,
          rephrase: event.metadata?.metadata?.rephrase || false,
          rephrasePrompt: event.metadata?.metadata?.rephrasePrompt || null,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          __typename: "Utterance",
        };
      case "stack" as const:
        return {
          id: eventId,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          update: event.update || "",
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "StackEvent",
        };
      case "action":
        return {
          id: eventId,
          actionText: event.name,
          conversationEventType: event.event.toUpperCase(),
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          name: event.name,
          slotValue: undefined,
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      case "slot" as const:
        return {
          id: eventId,
          actionText: undefined,
          conversationEventType: event.event.toUpperCase(),
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          name: event.name,
          slotValue: event.value,
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      case "memory_set":
      case "memory_cleared":
        return {
          id: eventId,
          actionText: undefined,
          conversationEventType: event.event.toUpperCase() as ConversationEventType,
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          name: event.key,
          value: event.event === "memory_cleared" ? null : event.value,
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      case "mcp_tool_executed":
      case "tool_executed": {
        const conversationEventType =
          event.event === "tool_executed"
            ? ConversationEventType.ToolExecuted
            : ConversationEventType.McpToolExecuted;
        const toolSource = event.event === "tool_executed" ? (event.source ?? "local") : "mcp";
        return {
          id: eventId,
          actionText: undefined,
          conversationEventType,
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
            tool_name: event.tool_name,
            tool_arguments: event.arguments,
            tool_result: event.result,
            tool_is_error: event.is_error,
            tool_error_message: event.error_message,
            tool_source: toolSource,
            tool_mcp_server: event.mcp_server,
          },
          name: event.tool_name || "tool",
          slotValue: undefined,
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      }
      case "agent_started":
      case "agent_completed":
      case "agent_cancelled":
      case "agent_interrupted":
      case "agent_resumed": {
        return {
          id: eventId,
          agentId: event.agent_id,
          actionText: undefined,
          conversationEventType: (event.event as string).toUpperCase() as ConversationEventType,
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          name: event.name,
          slotValue: undefined,
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      }
      case "skill_activated":
      case "skill_completed":
      case "skill_cancelled":
      case "skill_interrupted":
      case "skill_resumed": {
        return {
          id: eventId,
          skillId: event.skill_id,
          actionText: undefined,
          conversationEventType: event.event.toUpperCase() as ConversationEventType,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          name: event.skill_id,
          slotValue: undefined,
          stepId: event.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      }
      case "ordered_block_entered":
      case "ordered_block_completed":
      case "ordered_block_cancelled":
      case "ordered_block_interrupted":
      case "ordered_block_resumed": {
        return {
          id: eventId,
          skillId: event.skill_id,
          blockId: event.block_id,
          actionText: undefined,
          conversationEventType: event.event.toUpperCase() as ConversationEventType,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          name: event.block_id,
          slotValue: undefined,
          stepId: event.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      }
      case "bot_turn_ended":
        return {
          id: eventId,
          conversationEventType: event.event.toUpperCase(),
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      case "tts_finished":
        return {
          id: eventId,
          conversationEventType: event.event.toUpperCase(),
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      case "user_barge_in":
        return {
          id: eventId,
          conversationEventType: ConversationEventType.UserBargeIn,
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      case "user_silence_timeout":
        return {
          id: eventId,
          conversationEventType: ConversationEventType.UserSilenceTimeout,
          timeout: event.timeout,
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      case "user_input_suppressed":
        return {
          id: eventId,
          conversationEventType: ConversationEventType.UserInputSuppressed,
          modality: event.modality,
          reason: event.reason,
          text: event.text,
          flowId: event.flow_id || event.metadata?.active_flow,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
      default:
        return {
          id: eventId,
          actionText: undefined,
          conversationEventType: (event.event as string).toUpperCase(),
          flowId: event.flow_id || event.metadata?.active_flow,
          skillId: event.skill_id,
          metadata: {
            ...event.metadata,
            rawEvent: event,
          },
          name: event.name,
          slotValue: undefined,
          stepId: event.step_id || event.metadata?.step_id,
          timestamp: parsedTimestamp,
          originalTimestamp: event.timestamp,
          __typename: "ConversationEvent",
        };
    }
  });

  // TODO: this is a hacky workaround to add the flow and step info to the metadata
  //  since it is missing from the user uttered events
  //  if the info is missing from an event, it will be the same as the previous event
  const previousFlowState: { flow_id?: string; step_id?: string } = {
    flow_id: undefined,
    step_id: undefined,
  };

  for (const event of mappedEvents) {
    if (!event.metadata?.flow_id) {
      event.metadata.flow_id = previousFlowState.flow_id;
      event.metadata.step_id = previousFlowState.step_id;
      continue;
    }
    previousFlowState.flow_id = event.metadata.flow_id;
    previousFlowState.step_id = event.metadata.step_id;
  }

  return mappedEvents as UnionEventType[];
}

export const formatDateToLocale = (date: Date, locale?: Intl.LocalesArgument) => {
  const dateFormat: Intl.DateTimeFormatOptions = {
    timeZoneName: "short",
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
  };

  return date.toLocaleDateString(locale, dateFormat);
};

export const formatDateTime = (
  timestamp: Date | string | number,
  locale: Intl.LocalesArgument = "en-US",
) => {
  try {
    let date: Date;

    if (timestamp instanceof Date) {
      date = timestamp;
    } else if (typeof timestamp === "string" || typeof timestamp === "number") {
      const unixTimestamp =
        (typeof timestamp === "string" ? Number.parseFloat(timestamp) : timestamp) * 1000;
      date = new Date(unixTimestamp);
    } else {
      console.error("Invalid timestamp type:", typeof timestamp, timestamp);
      return "Invalid date";
    }

    // Check if the date is valid
    if (Number.isNaN(date.getTime())) {
      console.error("Invalid date:", timestamp);
      return "Invalid date";
    }

    return date.toLocaleString(locale, {
      month: "short",
      day: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false,
      timeZoneName: "short",
    });
  } catch (error) {
    console.error("Error formatting timestamp:", timestamp, error);
    return "Invalid date";
  }
};

/**
 * Converts a Date object to Unix timestamp string (seconds with fractional milliseconds)
 * @param date - The Date object to convert
 * @returns Unix timestamp as string (e.g., "1759832715.699")
 */
export const dateToUnixTimestamp = (date: Date): string => {
  // Get milliseconds since epoch and convert to seconds with fractional part
  const unixTimestamp = date.getTime() / 1000;
  return unixTimestamp.toString();
};

// Turn a flow/skill id or name into a readable label (drop default_/pattern_
// prefixes, underscores to spaces, capitalise).
export const formatSkillLabel = (idOrName: string): string => {
  const bare = idOrName
    .replace(/^(default_|pattern_)/, "")
    .replaceAll("_", " ")
    .trim();
  return bare ? bare.charAt(0).toUpperCase() + bare.slice(1) : bare;
};
